/* @lc app=leetcode id=3093 lang=kotlin */ class Solution { fun up(w: Array<String>, best: IntArray, i: Int, node: Int) { if (best[node] == -1 || w[i].length < w[best[node]].length) best[node] = i } fun stringIndices(wordsContainer: Array<String>, wordsQuery: Array<String>): IntArray = HashMap<Long, Int>().let { ch -> IntArray(wordsContainer.sumOf { it.length } + 2) { -1 }.let { best -> wordsContainer.indices.forEach { i -> up(wordsContainer, best, i, 0).let { wordsContainer[i].reversed().fold(0) { node, c -> ch.getOrPut(node * 26L + (c - 'a')) { ch.size + 1 }.also { up(wordsContainer, best, i, it) } } } }.let { wordsQuery.map { q -> q.reversed().fold(0 to true) { (node, go), c -> if (!go) node to false else ch[node * 26L + (c - 'a')]?.let { it to true } ?: (node to false) }.first.let { best[it] } }.toIntArray() } } } }